{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Ipratropium, a quaternary ammonium anticholinergic with a permanently charged N+ and tropane-like scaffold, has absolute oral bioavailability of only 2.0% in healthy volunteers, directly supporting low F for the similarly charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Physostigmine, a related alkaloid with an N-methylated aromatic amine, has mean absolute oral bioavailability of 3% as an oral solution in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, a moderately lipophilic tertiary amine opioid, has mean oral bioavailability of 18% in healthy subjects, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nitrendipine, despite nearly complete gastrointestinal absorption, has absolute oral bioavailability of 10.7 ± 4.7% in humans due to extensive first-pass metabolism/efflux, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Oxybutynin's (R)-enantiomer has an estimated oral bioavailability of 6.7% in a pharmacokinetic model, supporting low F for a lipophilic ester amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lisuride shows low oral bioavailability of 10% ± 7% at a 100 µg dose in humans, with higher values only at higher doses, supporting low F at typical exposures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "In surgical patients, physostigmine oral bioavailability was 25.3%, an outlier above the 20% threshold; however, multiple healthy-volunteer estimates are 1-8%, and the query's quaternary charge makes this less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (F < 20%) because the query is a permanently charged quaternary ammonium alkaloid; the most transferable direct analogue, ipratropium, has absolute oral bioavailability of ~2-3% in humans, and multiple related alkaloid/amine drugs show mean F values below 20%. Occasional higher values are dose- or condition-dependent outliers and do not outweigh the consistent low-F evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "The highest-transfer analogue (C39) reports a wide 5-40% range and is therefore not threshold-decisive.",
    "Some analogues show dose-dependent or condition-dependent F (e.g., lisuride 22.7% at 300 µg; physostigmine 25.3% in surgical patients), adding uncertainty.",
    "One retrieved record set (selegiline, C49/C23) appears inconsistent with its SMILES and was not used."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

